CREATE TABLE IF NOT EXISTS master_school(id BIGSERIAL PRIMARY KEY,school_id VARCHAR(100) UNIQUE NOT NULL,school_name VARCHAR(150) NOT NULL,email VARCHAR(254) UNIQUE NOT NULL,phone VARCHAR(20),database_name VARCHAR(63) UNIQUE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS master_user(id BIGSERIAL PRIMARY KEY,school_id VARCHAR(100) REFERENCES master_school(school_id),email VARCHAR(254) NOT NULL,password_hash TEXT NOT NULL,user_type VARCHAR(30) DEFAULT 'SCHOOL_ADMIN',created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(school_id,email));
CREATE TABLE IF NOT EXISTS master_subscription(id BIGSERIAL PRIMARY KEY,school_id VARCHAR(100) REFERENCES master_school(school_id),subscription_type VARCHAR(30) DEFAULT 'TRIAL',payment_status VARCHAR(30) DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS school_admission_listing(id BIGSERIAL PRIMARY KEY,school_id VARCHAR(100) REFERENCES master_school(school_id),school_name VARCHAR(150) NOT NULL,academic_year VARCHAR(20) NOT NULL,class_name VARCHAR(50) NOT NULL,total_seats INT DEFAULT 0 CHECK(total_seats>=0),available_seats INT DEFAULT 0 CHECK(available_seats>=0 AND available_seats<=total_seats),admission_open BOOLEAN DEFAULT FALSE,UNIQUE(school_id,academic_year,class_name));
